  'pythia_nucleus': '/root/autodl-tmp/recursive_gen_depth_est/data/features_all.jsonl',
  'pythia_temp09': '/root/autodl-tmp/recursive_gen_depth_est/data/pythia_temp09/features.jsonl',
  'olmo_nucleus': '/root/autodl-tmp/recursive_gen_depth_est/data/olmo/features.jsonl',
  'gpt2xl_nucleus': '/root/autodl-tmp/recursive_gen_depth_est/data/gpt2xl/features.jsonl',
}
result = {}
for cell, path in files.items():
    depth_sums = {}
    depth_counts = {}
    with open(path) as f:
        for line in f:
            r = json.loads(line)
            d = r['depth']
            if d not in depth_sums:
                depth_sums[d] = {feat: 0.0 for feat in features}
                depth_counts[d] = 0
            depth_counts[d] += 1
            for feat in features:
                depth_sums[d][feat] += r.get(feat, 0.0)
    means = {}
    for d in sorted(depth_sums.keys()):
        means[str(d)] = {feat: depth_sums[d][feat] / depth_counts[d] for feat in features}
    result[cell] = {'n_per_depth': {str(d): depth_counts[d] for d in sorted(depth_counts.keys())}, 'means': means}
print(json.dumps(result))
"

