import json

features = ['mean_ppl','var_ppl','skewness_ppl','kurtosis_ppl','p10_ppl','p25_ppl','p50_ppl','p75_ppl','p90_ppl','mean_surprisal','var_surprisal','entropy_of_surprisal','type_token_ratio','hapax_ratio','bigram_entropy','trigram_entropy','rep_2gram','rep_3gram','rep_4gram']
files = {
  'pythia_nucleus': 'data/features_all.jsonl',
  'pythia_temp09': 'data/pythia_temp09/features.jsonl',
  'olmo_nucleus': 'data/olmo/features.jsonl',
  'gpt2xl_nucleus': 'data/gpt2xl/features.jsonl',
}
result = {}
for cell, path in files.items():
    depth_sums = {}
    depth_counts = {}
    with open(path) as f:
        for line in f:
            r = json.loads(line)
            d = r['depth']
            if d not in depth_sums:
                depth_sums[d] = {feat: 0.0 for feat in features}
                depth_counts[d] = 0
            depth_counts[d] += 1
            for feat in features:
                depth_sums[d][feat] += r.get(feat, 0.0)
    means = {}
    for d in sorted(depth_sums.keys()):
        means[str(d)] = {feat: round(depth_sums[d][feat] / depth_counts[d], 6) for feat in features}
    result[cell] = {'n_per_depth': {str(d): depth_counts[d] for d in sorted(depth_counts.keys())}, 'means': means}
print(json.dumps(result))
"

